 overflow: hidden;
}

.slider-track {
 display: flex;
 transition: transform 0.5s ease;
}

.slider-slide {
 flex: 0 0 50%;
 padding: 0 6px;
 box-sizing: border-box;
}

.slider-slide img {
 display: block;
 width: 100%;
 height: auto;
 border-radius: 0px;
}

.slider-arrow {
 position: absolute;
 top: 50%;
 transform: translateY(-50%);
 width: 44px;
 height: 44px;
 border: none;
 border-radius: 50%;
 background: rgba(0,0,0,.6);
 color: #fff;
 cursor: pointer;
 z-index: 10;
 font-size: 22px;
}

.slider-arrow:hover,
.slider-arrow:focus {
 background: rgba(0,0,0,.8);
}

.prev {
 left: 12px;
}

.next {
 right: 12px;
}

@media (max-width: 1024px) {

 .slider-slide {
 flex: 0 0 100%;
 padding: 0;
 }

