<script>
(function () {

 const sourceImages =
 document.querySelectorAll('.slider-images img');

 const slider =
 document.querySelector('.kpmg-slider');

 const track =
 document.querySelector('.slider-track');

 const nextBtn =
 document.querySelector('.next');

 const prevBtn =
 document.querySelector('.prev');

 let currentIndex = 0;
 let autoPlay;

 function getVisibleSlides() {

 return window.innerWidth <= 1024 ? 1 : 2;

 }

 sourceImages.forEach((img) => {

 const slide =
 document.createElement('div');

 slide.className = 'slider-slide';

 const image =
 document.createElement('img');

 image.src = img.src;
 image.alt = img.alt;

 slide.appendChild(image);
 track.appendChild(slide);

 });

 function updateSlider() {

 const visibleSlides =
 getVisibleSlides();

 const translate =
 currentIndex * (100 / visibleSlides);

 track.style.transform =
 `translateX(-${translate}%)`;

 }

 function getMaxIndex() {

 const visible = getVisibleSlides();

 if (visible === 1) {
 return sourceImages.length - 1;
 }

 return Math.floor((sourceImages.length - 1) / 2) * 2;

 }

 function nextSlide() {

 const step = getVisibleSlides();

 currentIndex += step;

 if (currentIndex > getMaxIndex()) {
 currentIndex = 0;
 }

 updateSlider();

 }

 function previousSlide() {

 const step = getVisibleSlides();

 currentIndex -= step;

 if (currentIndex < 0) {

 currentIndex = getMaxIndex();

 if (step === 2 && currentIndex % 2 !== 0) {
 currentIndex--;
 }

 }

 updateSlider();

 }

 function startAutoPlay() {

 stopAutoPlay();

 autoPlay = setInterval(
 nextSlide,
 5000
 );

 }

 function stopAutoPlay() {

 clearInterval(autoPlay);

 }

 nextBtn.addEventListener(
 'click',
 () => {

 nextSlide();
 startAutoPlay();

 }
 );

 prevBtn.addEventListener(
 'click',
 () => {

 previousSlide();
 startAutoPlay();

 }
 );

 slider.addEventListener(
 'mouseenter',
 stopAutoPlay
 );

 slider.addEventListener(
 'mouseleave',
 startAutoPlay
 );

 let touchStart = 0;

 slider.addEventListener(
 'touchstart',
 (e) => {

 touchStart =
 e.changedTouches[0].clientX;

 },
 { passive: true }
 );

 slider.addEventListener(
 'touchend',
 (e) => {

 const touchEnd =
 e.changedTouches[0].clientX;

 const distance =
 touchStart - touchEnd;

 if (Math.abs(distance) > 50) {

 if (distance > 0) {

 nextSlide();

 } else {

 previousSlide();

 }

 startAutoPlay();

 }

 },
 { passive: true }
 );

 window.addEventListener(
 'resize',
 () => {

 if (currentIndex > getMaxIndex()) {

 currentIndex =
 getMaxIndex();

 }

 updateSlider();

 }
 );

 updateSlider();
 startAutoPlay();

})();
</script>","cssPaths":[],"jsPaths":[]}}">
Flexible ways of working
Our approach to work is built on trust, flexibility, wellbeing and development. You'll work across client sites, the office and home while staying connected to your team, continuing to learn and delivering great outcomes for clients.
Your career is important, but so is everything around it.
At KPMG, you'll find opportunities to learn, connect, develop and make the most of your experience both inside and outside of work.

At U.S. Bank, we’re on a journey to do our best. Helping the customers and businesses we serve to make better and smarter financial decisions and enabling the communities we support to grow and succeed. We believe it takes all of us to bring our shared ambition to life, and each person is unique in their potential. A career with U.S. Bank gives you a wide, ever-growing range of opportunities to discover what makes you thrive at every stage of your career. Try new things, learn new skills and discover what you excel at—all from Day One.

 We actively uphold transparent and fair hiring practices that support individual opportunity, inclusive culture, and career mobility across all levels of our organisation.

 We offer meaningful opportunities for growth, a culture of inclusion, and a strong commitment to transparency and integrity in everything we do.

 Job Description Job Description

 About U.S. Bank Global Fund Services (Ireland) Limited 

 U.S. Bank Global Fund Services (Ireland) Limited is a hedge fund administration specialist based at City Quay in the IFSC. Our innovative technology, coupled with a talented and motivated workforce allows us to deliver a superior service to our clients. We are committed to our services being of the highest quality and are continuously improving our technologies and processes, therefore offering challenging, dynamic roles with excellent career prospects.

 Role overview: 

 The Investor Services Analyst works under the guidance of a Supervisor / Assistant Manager. The candidate will be expected to perform to a high standard all tasks detailed below. The Investor Services Analyst provides support to the group as a whole and therefore needs to be flexible and display an ability to adapt to different funds and deadlines.

 Key accountabilities: 

 • Processing and confirming subscriptions, redemptions, switches and transfers;
 • Processing payments and other transactions;
 • Applying the Net Asset Value to investor capital activity for daily / weekly / monthly Funds;
 • Completing audit requests for investor accounts;
 • Responding to investor and client queries via email and phone;
 • Adhere to all processing procedures and controls;
 • Act as primary contact for both client and investor queries and act as host for client service calls and monthly board calls;
 • Ensure client month-end reporting deliverables are being met;
 • Gain an understanding of all funds across the team in order to provide coverage when required;
 • Maintain a good working relationship with external clients as well as with internal relationship managers and other business units within UBSGFSI;
 • Maintaining shareholders registers and acting as transfer agent;
 • Communicating with investors;
 • Performing all of the investor related services of the Company's investment fund clients;
 • Meeting expectations of fund participants, adhering to deadlines;
 • Maintaining relationships with investors, investment advisors/managers, banks, brokers and auditors and other fund participants;

 Skills & experience required: 

 • Leaving Certificate and 3rd Level Qualification
 • Attention to detail
 • Good organizational and administration skills with a high attention to detail
 • Strong interpersonal skills
 • Strong oral and written communication skills • Excellent client service skills

 Additional information 
 The role offers a hybrid / flexible schedule, which means there's an in-office expectation of 3 or more days per week and the flexibility to work outside the office location for the other days.

  

 This position is not eligible for visa sponsorship. 


 Accessibility 
 We are committed to providing an inclusive and accessible recruitment experience. If you need adjustments at any stage of the application or hiring process, please contact your recruiter for guidance and support. 

 Total Rewards 
 U.S. Bank is committed to fair, equitable, and transparent compensation practices in line with local regulatory and legal requirements. Our total rewards approach is designed to attract, retain, and support top talent while ensuring equal pay for work of equal value.
  
 We offer a market-competitive compensation package that includes:
 Clearly defined salary ranges aligned with industry benchmarks and internal equity standards.

 Performance-based incentives for eligible employees (as defined by relevant plan rules), awarded through transparent, objective criteria that recognize both individual and company performance.

 Inclusive equitable benefits that are accessible to all employees and focused around our 3 main pillars of financial wellbeing, health & wellness).

 Continuous development opportunities including training, education support, and career progression pathways based on inclusive and transparent criteria.

 Employee recognition programs that celebrate achievements and milestones for all.

  
 We regularly review our compensation and benefits to ensure they remain competitive, inclusive, and responsive to employee needs and market trends. Further details of the compensation package will be provided upon application.

 We encourage candidates to explore the full value of our offer, including monetary and non-monetary benefits, at Employee benefits and development | U.S. Bank | Elavon .
   
 Closing Date 
 Posting may be closed earlier due to high volume of applicants.
  
 We aim to provide timely updates throughout the process and encourage early applications to ensure consideration.

About us  
 At Davy, it’s the unique talents of all our people that have been the foundations of our success for 100 years. As we continue to grow, so do you. Because you are not just part of our team – you are a key player in shaping our future.  
 At Davy, you are the difference.   
 Established in 1926, the Davy Group sits at the heart of wealth and capital in Ireland, providing a broad range of services to high-net-worth individuals, self-directed investors, small-to-medium enterprises, credit unions, corporations, and domestic & international institutional investors.  
 Our culture is shaped around three values, which are at the heart of everything we do: client success, one Davy, and building a proud legacy. Sharing the same goals, we work together to deliver exceptional outcomes for our clients. As part of a team of over 900, you will be encouraged to learn and to grow, both professionally and personally. of a team of over 900, you will be encouraged to learn and to grow, both professionally and personally. 
 An opportunity has arisen for an Investment Associate within the Private Clients department at Davy. The successful candidate will:
 About the role 
 Work closely with an Associate Director/Director:
 Assist in the creation and execution of relationship plans for each client relating to the implementation of their financial plan, adherence with service standards which lead to the development of long-term client relationships;
 Identify revenue potential and opportunities to cross-sell Davy services;
 Review existing client relationships, and in line with Investment Strategy, analyse whether the relationships are categorised correctly and therefore managed appropriately;
 Execute a engagement plan for each advisory relationship to ensure they receive proactive, relevant and appropriate contact, investment ideas and recommendations and structured portfolio reviews;
 Manage MI relating to client relationships;
 Deal promptly and efficiently with client queries;
 Ensure that all activities and duties are carried out in full compliance with regulatory requirements, Davy’s Risk Management Framework and internal Policies and Policy Standards;
 Be recognised as an expert and influential contact for Davy’s services and in relation to client queries;
 Network with peers at industry events.
 Comply with the Risk and Compliance frameworks, policies and procedures associated with the role
 Requirements 
 About you 
 Degree or Masters in Business related area;
 2-3 years industry experience;
 QFA qualification;
 A high degree of proficiency in Microsoft Office applications, particularly Excel, Word and PowerPoint;
 Proficient in CRM;
 A commitment to further education and continuous learning;
 Demonstrable interest and understanding of investments;
 A strong client focus, to ensure effective service delivery;
 Strong communication and presentation skills;
 Excellent attention to detail;
 Excellent organisational skills;
 An ability to prioritise own workload.

 The position set out above is defined as a “Controlled Function (CF)” role, namely CF3, CF4, CF10.under Section 20 of the Central Bank Reform Act 2010 and Schedule 1 of the Regulations (S.I. No. 437 of 2011) as amended. In accordance with Section 21 of the Central Bank Reform Act 2010 and the Fitness and Probity Standards 2014, any offer of employment is conditional upon you demonstrating that you meet the Fitness & Probity requirements, applicable to this position. The role is also subject to the Minimum Competency Code and therefore there is a requirement to hold, or be willing to take the APA (Regulation & Investment) or (Pensions) or Registered Stockbroker or QFA exams. 
 Benefits 
 What we offer  
 At Davy, our people are our biggest investment. In today’s fast-moving world, we know it’s important to feel secure and empowered. That’s why Davy benefits support you through all of life’s stages, offering health and wellness, flexible working options, flexible benefits allowance, learning and development opportunities, through to assisted retirement planning.  
 Health and Wellbeing  
 Psychological safety, emotional wellbeing and support are a priority at Davy. We offer a comprehensive Employee Assistance Programme (EAP) and mental health first aid. Our Sports & Social teams promote physical wellbeing and social connection. 
 Reward and Recognition  
 We offer a competitive remuneration package to include salary, bonus, pension and a host of additional benefits to protect you and your family when it matters most. 
 Growth and Development  
 Our award-winning L&D function supports you and your growth at Davy. We offer a comprehensive range of professional and personal development opportunities. Our culture supports learning, and we encourage you to explore more at Davy. 
 Positive Workplace  
 Our workplace is inclusive, diverse, and offers everyone a sense of belonging. We are flexible and continue to support a hybrid working model. You will get to be your best at Davy. 
 Values and Culture  
 Exceptional client outcomes delivered by a world class team, underpinned by our core Davy values – One Team, Client Success, and Proud Legacy.  
 Important Information  
 Davy is an equal opportunities employer, committed to fostering an inclusive and diverse workplace. We value diversity in both background and experience, and even if you don’t meet all of the requirements outlined in the job description, we still encourage you to apply. We review all applications received. As part of our commitment to creating an accessible environment, we want to ensure that everyone has an equal opportunity to participate in the interview process. If you require any reasonable accommodations, please let us know, and we will do our best to make the necessary arrangements.  
 Appointment to this role is subject to the candidate's eligibility to work in Ireland.
 Where agency assistance is required, our Recruitment Team will engage directly with suppliers. Unsolicited CVs / profiles supplied to us by recruitment agencies will not be accepted for this role. 
 Davy Group is a member of the Bank of Ireland Group.

